    height: 100%;
    background-color: #eee;
}

.product-card h3 {
    font-size: 1rem;
    margin-bottom: 4px;
}

.product-price {
    font-weight: 700;
    color: var(--color-accent);
    display: block;
    margin-bottom: var(--spacing-sm);
}

.add-to-cart {
    width: 100%;
    padding: 0.5rem;
    font-size: 0.8rem;
}

/* Editorial */
.editorial {
    padding: var(--spacing-xl) 0;
}

.editorial-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-lg);
    align-items: center;
}

.editorial-media {
    height: 400px;
    background: #eee;
}

.editorial-text h2 {
    font-size: 2.5rem;
    margin-bottom: var(--spacing-md);
}

.editorial-text p {
    font-size: 1.1rem;
    color: var(--color-text-light);
    margin-bottom: var(--spacing-md);
}

