footer {
    background: var(--color-primary);
    color: var(--color-white);
    padding: var(--spacing-xl) 0 var(--spacing-md);
}

.footer-container {
    display: grid;
    grid-template-columns: 1fr 2fr;
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-lg);
}

.footer-brand .logo {
    margin-bottom: var(--spacing-sm);
}

.footer-nav {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: var(--spacing-md);
}

.footer-column h3 {
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: var(--spacing-md);
}

.footer-column ul li {
    margin-bottom: var(--spacing-xs);
}

.footer-column a {
    color: #ccc;
    font-size: 0.9rem;
}

.footer-column a:hover {
    color: var(--color-white);
}

.newsletter-form label {
    display: block;
    font-size: 0.8rem;
    margin-bottom: var(--spacing-xs);
}

.input-group {
    display: flex;
}

.input-group input {
    flex: 1;
    padding: 0.5rem;
    border: none;
}

.footer-bottom {
    border-top: 1px solid #333;
    padding-top: var(--spacing-md);
    text-align: center;
    font-size: 0.8rem;
    color: #999;
}

/* Mobile Nav */
.mobile-nav-toggle {
    display: none;
}

@media (max-width: 768px) {
    :root {
        --spacing-lg: 2rem;
        --spacing-xl: 3rem;
    }

    .hero-container, .deals-grid, .editorial-grid, .footer-container {
        grid-template-columns: 1fr;
    }

    .hero h1 {
        font-size: 2.5rem;
    }

    .nav-links {
        display: none;
    }

    .mobile-nav-toggle {
        display: block;
        background: none;
        border: none;
        cursor: pointer;
    }

    .hamburger, .hamburger::before, .hamburger::after {
        display: block;
        width: 24px;
        height: 2px;
        background: var(--color-text);
        transition: var(--transition);
        position: relative;
    }

    .hamburger::before, .hamburger::after {
        content: '';
        position: absolute;
        left: 0;
    }

    .hamburger::before { top: -8px; }
    .hamburger::after { bottom: -8px; }

    .footer-nav {
        grid-template-columns: 1fr 1fr;
    }
}
